T.copy_alloc_root_t = function(s) return {first = s.first, current = s.current} end

T.TStorageVol = function() return {k = 0, v = 0.0} end
T.copy_TStorageVol = function(s) return {k = s.k, v = s.v} end

T.TAvgResults = function() return {} end
T.copy_TAvgResults = function(s) return {xAvg = s.xAvg} end

T.TUHData = function() return {period = 0, hasPastRain = 0, maxPeriods = 0, drySeconds = 0, iaUsed = 0.0} end
T.copy_TUHData = function(s) return {pastRain = s.pastRain, pastMonth = s.pastMonth, period = s.period, hasPastRain = s.hasPastRain, maxPeriods = s.maxPeriods, drySeconds = s.drySeconds, iaUsed = s.iaUsed} end

T.TUHGroup = function() return {isUsed = 0, rainInterval = 0, area = 0.0, rdii = 0.0, gageDate = 0.0, lastDate = 0.0, uh = R.recs(3, T.TUHData)} end
T.copy_TUHGroup = function(s) return {isUsed = s.isUsed, rainInterval = s.rainInterval, area = s.area, rdii = s.rdii, gageDate = s.gageDate, lastDate = s.lastDate, uh = R.copyRecs(s.uh, T.copy_TUHData)} end

T.TXsectStar = function() return {s = 0.0, qc = 0.0} end
T.copy_TXsectStar = function(s) return {s = s.s, qc = s.qc, xsect = s.xsect} end

